## 2. Adding Undo/Redo

A common extension is to let commands support an `Undo()` operation.  
We’ll modify the interface and provide concrete commands that remember state.

```csharp
namespace CommandPatternDemo
{
    public interface IUndoableCommand : ICommand
    {
        void Undo();
    }

    // Light command with undo
    public class LightOnCommand : IUndoableCommand
    {
        private readonly Light _light;
        public LightOnCommand(Light light) => _light = light;

        public void Execute() => _light.TurnOn();

        public void Undo() => _light.TurnOff();
    }

    public class LightOffCommand : IUndoableCommand
    {
        private readonly Light _light;
        public LightOffCommand(Light light) => _light = light;

        public void Execute() => _light.TurnOff();

        public void Undo() => _light.TurnOn();
    }

    // Simple command history for redo
    public class CommandHistory
    {
        private readonly Stack<IUndoableCommand> _undoStack = new Stack<IUndoableCommand>();
        private readonly Stack<IUndoableCommand> _redoStack = new Stack<IUndoableCommand>();

        public void Execute(IUndoableCommand cmd)
        {
            cmd.Execute();
            _undoStack.Push(cmd);
            _redoStack.Clear();
        }

        public void Undo()
        {
            if (_undoStack.Count == 0) return;
            var cmd = _undoStack.Pop();
            cmd.Undo();
            _redoStack.Push(cmd);
        }

        public void Redo()
        {
            if (_redoStack.Count == 0) return;
            var cmd = _redoStack.Pop();
            cmd.Execute();
            _undoStack.Push(cmd);
        }
    }
}
```

**Client usage**

```csharp
public class Program
{
    public static void Main()
    {
        var light = new Light();
        var history = new CommandHistory();

        var on = new LightOnCommand(light);
        var off = new LightOffCommand(light);

        history.Execute(on);   // Light ON
        history.Execute(off);  // Light OFF

        history.Undo();        // Light ON again
        history.Undo();        // Light OFF again

        history.Redo();        // Light ON
    }
}
```

